ANNOTATIONS = [
    (30, 'before', '''内部模型名允许出现在 commit trailer 的仓库白名单：同时收录 SSH 与 HTTPS 两种 URL 形式。注意这里是「按仓库」放行而非「按组织」——anthropics 与 anthropic-experimental 组织里也有公开仓库（如 claude-code、sandbox-runtime），那些必须保持 undercover 模式开启以防代号泄露；只有确认是私有的仓库才加进来。'''),
    (83, 'before', '''取归因用的仓库根：先取 cwd（尊重 agent 的 worktree 覆盖，基于 AsyncLocalStorage），再解析到 git 根以处理 cd 进子目录的情况；解析不出 git 根就退回原始工作目录。'''),
    (92, 'before', '''仓库分类结果的进程级缓存：internal 表示远程命中白名单、external 表示有远程但不在白名单（公开仓库）、none 表示没有远程。每个进程只算一次。'''),
    (98, 'before', '''同步返回缓存里的仓库分类；若异步检查还没跑过则返回 null。'''),
    (106, 'before', '''同步返回「是否在内部模型仓库」的缓存结果；检查还没跑过时返回 false——安全默认值：宁可不要泄露。'''),
    (114, 'before', '''判断是否处于「允许用内部模型名」的白名单仓库：用 sequential 包成「每进程只查一次」。先解析仓库根、取远程 URL，命中白名单任一项即 internal，否则 external；没有远程就是 none。'''),
    (135, 'before', '''把 surface key 规整成「公开模型名」版本：按最后一个斜杠拆成 surface 与 model 两段，对 model 段跑一遍模型名净化，再拼回 surface/净化后模型。'''),
    (154, 'before', '''把内部模型名映射到公开等价名：按模型家族逐级判断（opus-4-6 / opus-4-5 / sonnet-4-6 …），命中哪个家族就返回对应的 claude-xxx 公开名；不认识的统归为 claude。新增模型时在 @[MODEL LAUNCH] 注释处补一条映射，否则 trailer 会显示内部名。'''),
    (173, 'before', '''一次会话的归因状态：fileStates 按相对路径记每个文件的 Claude 贡献；sessionBaselines 记会话基线（内容哈希 + mtime）用于算净变更；surface 记编辑来自哪个端；startingHeadSha 记会话开始时的 HEAD（用来检测外部提交）；还有 promptCount / permissionPromptCount / escapeCount 及其「上次提交时」的快照值，用于算每次提交的 steer 数。'''),
    (197, 'before', '''一次提交里 Claude 贡献的汇总：Claude 占比、Claude 字符数、人类字符数、涉及的 surface 列表。'''),
    (207, 'before', '''写进 git notes 的「每文件」归因明细：Claude 字符、人类字符、占比、来源 surface。'''),
    (217, 'before', '''git notes JSON 的完整归因数据：版本号、汇总、每文件明细、按 surface 的构成分解、被排除的生成文件列表、会话 ID 列表。'''),
    (229, 'before', '''从环境变量取当前客户端 surface：取 CLAUDE_CODE_ENTRYPOINT，没设就默认 cli。'''),
    (237, 'before', '''构造带模型名的 surface key：格式 surface/model（如 cli/claude-sonnet），模型名用 getCanonicalName 归一到规范名。'''),
    (244, 'before', '''算内容的 SHA-256 哈希：用于给文件状态做内容指纹，比对基线是否变化。'''),
    (252, 'before', '''把文件路径归一化成「相对 cwd 的相对路径」以便一致追踪：会解析符号链接（如 macOS 上 /tmp 与 /private/tmp），并把分隔符统一成正斜杠以兼容 Windows 下 git diff 的输出。绝对路径不在 cwd 之内就原样返回。'''),
    (296, 'before', '''把相对路径展开成绝对路径：相对路径就拼上仓库根，绝对路径原样返回。'''),
    (306, 'before', '''为新会话造一份空的归因状态：各计数器归零、surface 取客户端 surface、基线为空。'''),
    (325, 'before', '''算一次文件修改的字符级贡献：新建或整删时贡献等于内容长度；否则用「公共前缀 / 公共后缀」匹配找出真正改动的区段（这样「Esc」改成「esc」这种等长替换也能正确计量，而 Math.abs 差值会算成 0）。贡献累加到该文件已有状态上，算不出就返回 null。'''),
    (387, 'before', '''取文件的 mtimeMs，文件不存在时退回 Date.now()：做成异步是为了能在进入同步的 setAppState 回调前预计算好。'''),
    (402, 'before', '''追踪一次「Claude 改了文件」：在 Edit / Write 工具完成后调用，算出贡献后写进状态的 fileStates（不可变更新，复制整份 Map）。'''),
    (439, 'before', '''追踪一次「Claude 建了文件」（如经 bash 命令）：本质上就是「从空内容变成新内容」的一次修改，直接复用 trackFileModification。'''),
    (453, 'before', '''追踪一次「Claude 删了文件」（如经 bash rm）：删掉的字符数累加到该文件已有贡献上，已删文件的内容哈希记为空串。'''),
    (489, 'before', '''批量追踪多处文件改动：只复制一份 Map 然后逐文件原地改，避免处理超大 git diff（如 jj 一次动几十万个文件）时「每文件复制一次 Map」的 O(n²) 代价。'''),
    (548, 'before', '''计算「暂存文件」的最终归因：把多个会话的状态合并（基线取最早、贡献累加），再并行处理每个暂存文件——跳过生成文件、删除文件区分 Claude 删还是人类删、未追踪的修改按 git diff 大小估算人类字符；最后算出每文件明细、总量、Claude 占比、按 surface 的构成分解。'''),
    (751, 'before', '''从 git diff 估算一个文件的改动字符数：用 git diff --cached --stat 抓摘要，对「N files changed, X insertions, Y deletions」这类汇总行，把插入 + 删除的行数乘以约 40（每行平均字符）当作字符数。'''),
    (793, 'before', '''判断一个文件在暂存改动里是否被删：用 git diff --cached --name-status 看输出是不是以 D 加制表符开头。'''),
    (817, 'before', '''取当前暂存的文件列表：git diff --cached --name-only，出错的按空列表处理。'''),
    (843, 'before', '''判断 git 是否处于「瞬态」：rebase / merge / cherry-pick / bisect 进行中（通过检查 .git 下的 rebase-merge、MERGE_HEAD、CHERRY_PICK_HEAD、BISECT_LOG 这些标记文件是否存在）。'''),
    (872, 'before', '''把归因状态序列化成「快照消息」以便持久化：把 Map 形式的 fileStates 摊平成普通对象，连同各类计数器一起打包成 attribution-snapshot 消息。'''),
    (899, 'before', '''从快照消息恢复归因状态：快照是「整份状态」而非增量，最后一个快照对每个路径都持有最新计数（fileStates 只会增长）。注释里特意点出——若跨所有快照把计数累加会二次方膨胀（837 个快照 × 280 文件会算成 1.15 千万亿「字符」），所以这里只取最后一个快照。'''),
    (934, 'before', '''会话恢复时从日志快照重建归因状态：调上面的恢复函数再回调 onUpdateState 把新状态推出去。'''),
    (950, 'before', '''递增 promptCount 并保存一份归因快照：用于在压缩（compaction）之间跨轮持久化提示计数；先复制状态把 promptCount +1，再生成快照交给调用方异步保存。'''),
]
